function formatSure(sn) {
  const m = Math.floor(sn / 60);
  const s = sn % 60;
  return `${m}:${s.toString().padStart(2, "0")}`;
}

function durumRengi(kalan) {
  if (kalan <= 60) return COLORS.red;
  if (kalan <= 300) return COLORS.amber;
  return COLORS.green;
}

// ---- Geri sayim halkasi: imza bilesen ----
function CountdownRing({ kalan, toplam = 900, size = 52 }) {
  const oran = Math.max(0, Math.min(1, kalan / toplam));
  const renk = durumRengi(kalan);
  const r = (size - 6) / 2;
  const c = 2 * Math.PI * r;
  return (
    <div style={{ position: "relative", width: size, height: size, flexShrink: 0 }}>
      <svg width={size} height={size} style={{ transform: "rotate(-90deg)" }}>
        <circle cx={size / 2} cy={size / 2} r={r} stroke={COLORS.line} strokeWidth="4" fill="none" />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={r}
          stroke={renk}
          strokeWidth="4"
          fill="none"
          strokeDasharray={c}
          strokeDashoffset={c * (1 - oran)}
          strokeLinecap="round"
          style={{ transition: "stroke-dashoffset 1s linear" }}
        />
      </svg>
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: 11,
          fontWeight: 700,
          color: renk,
        }}
        className="display"
      >
        {formatSure(kalan)}
      </div>
    </div>
  );
}

// ---------------- Ortak iPhone govdesi: durum cubugu + baslik + icerik + alt tab bar ----------------
function PhoneShell({ logo, logoAlt = "Eminevim", title, subtitle, children, tabs, activeTab, onTabChange }) {
  return (
    <div
      style={{
        width: 375,
        maxWidth: "100%",
        background: COLORS.navyDeep,
        borderRadius: 44,
        padding: 12,
        boxShadow: "0 30px 60px -20px rgba(14,42,71,0.45)",
      }}
    >
      <div style={{ background: COLORS.bg, borderRadius: 34, overflow: "hidden", height: 690, display: "flex", flexDirection: "column" }}>
        {/* Durum cubugu */}
        <div style={{ height: 30, background: COLORS.navyDeep, flexShrink: 0 }} />

        {/* Baslik */}
        <div style={{ background: COLORS.navy, padding: "16px 20px 20px", flexShrink: 0 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <img src={logo} alt={logoAlt} style={{ height: 16 }} />
            <span
              style={{
                color: "#B9C7D6",
                fontSize: 11,
                fontWeight: 600,
                letterSpacing: 0.4,
                borderLeft: "1px solid #3A4B67",
                paddingLeft: 8,
              }}
            >
              {title}
            </span>
          </div>
          {subtitle}
        </div>

        {/* Icerik (kaydirilabilir) */}
        <div style={{ flex: 1, overflowY: "auto", minHeight: 0 }}>{children}</div>

        {/* Alt tab bar */}
        {tabs && (
          <div
            style={{
              flexShrink: 0,
              display: "flex",
              borderTop: `1px solid ${COLORS.line}`,
              background: "#fff",
              paddingBottom: 6,
              paddingTop: 6,
            }}
          >
            {tabs.map((t) => {
              const aktif = activeTab === t.id;
              const Icon = t.icon;
              return (
                <button
                  key={t.id}
                  onClick={() => onTabChange(t.id)}
                  style={{
                    flex: 1,
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    gap: 3,
                    background: "transparent",
                    border: "none",
                    cursor: "pointer",
                    padding: "4px 0",
                  }}
                >
                  <Icon size={20} color={aktif ? COLORS.steel : "#A7B3AC"} strokeWidth={aktif ? 2.4 : 2} />
                  <span style={{ fontSize: 10, fontWeight: aktif ? 700 : 500, color: aktif ? COLORS.steel : "#A7B3AC" }}>
                    {t.label}
                  </span>
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

// ---------------- SPY Paneli (iPhone) ----------------
function SpyPaneli() {
  const [basvurular, setBasvurular] = useState(initialBasvurular);
  const [tab, setTab] = useState("liste");

  useEffect(() => {
    const t = setInterval(() => {
      setBasvurular((prev) => prev.map((b) => ({ ...b, kalan: Math.max(0, b.kalan - 1) })));
    }, 1000);
    return () => clearInterval(t);
  }, []);

  const siraliListe = basvurular.slice().sort((a, b) => a.kalan - b.kalan);

  return (
    <PhoneShell
      logo={LOGO_BEYAZ}
      title="SPY PANELI"
      subtitle={
        <>
          <div className="display" style={{ color: "#fff", fontSize: 22, fontWeight: 800, marginTop: 10 }}>
            Siradaki Gorusmeler
          </div>
          <div style={{ color: "#8FA3B8", fontSize: 12, marginTop: 4 }}>Onur K. - Kadikoy / Atasehir bolgesi</div>
        </>
      }
      tabs={[
        { id: "liste", label: "Gorusmeler", icon: Clock },
        { id: "gecmis", label: "Gecmis", icon: LayoutGrid },
        { id: "profil", label: "Profil", icon: User },
      ]}
      activeTab={tab}
      onTabChange={setTab}
    >
      {tab === "liste" && (
        <div style={{ padding: 14, display: "flex", flexDirection: "column", gap: 10 }}>
          {siraliListe.map((b, i) => (
            <div
              key={b.id}
              style={{
                background: COLORS.card,
                borderRadius: 14,
                padding: 12,
                display: "flex",
                alignItems: "center",
                gap: 12,
                border: `1px solid ${COLORS.line}`,
                borderLeft: `4px solid ${i === 0 ? COLORS.gold : COLORS.line}`,
              }}
            >
              <CountdownRing kalan={b.kalan} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <span style={{ fontSize: 14, fontWeight: 700, color: COLORS.navy }}>{b.ad}</span>
                  {i === 0 && (
                    <span
                      style={{
                        fontSize: 9,
                        fontWeight: 700,
                        color: COLORS.gold,
                        border: `1px solid ${COLORS.gold}`,
                        borderRadius: 6,
                        padding: "1px 5px",
                      }}
                    >
                      SIRADA
                    </span>
                  )}
                </div>
                <div style={{ fontSize: 12, color: COLORS.textDim, marginTop: 2 }}>
                  {b.ilce} - {b.mesafeKm} km uzaklikta
                </div>
              </div>
              <button
                style={{
                  background: COLORS.navy,
                  color: "#fff",
                  border: "none",
                  borderRadius: 10,
                  padding: "8px 12px",
                  fontSize: 12,
                  fontWeight: 700,
                  cursor: "pointer",
                }}
              >
                Don
              </button>
            </div>
          ))}
        </div>
      )}

      {tab === "gecmis" && (
        <div style={{ padding: 30, textAlign: "center", color: COLORS.textDim, fontSize: 13 }}>
          Tamamlanmis gorusme gecmisi burada listelenecek.
        </div>
      )}

      {tab === "profil" && (
        <div style={{ padding: 30, textAlign: "center", color: COLORS.textDim, fontSize: 13 }}>
          SPY profil ve performans bilgileri burada gosterilecek.
        </div>
      )}
    </PhoneShell>
  );
}

// ---------------- Admin Paneli (iPhone) ----------------
